insert into requisito_agrupada (id, parent_id, secao, numero, rotulo, texto, faixas, revisao) values ('171e9b13-ab35-5a37-bdf8-538a14800b79', null, 'VIII - Arte de Acampar', 316, 'VIII.4', 'Fazer um fogo refletor e demonstrar seu uso.', '{13,14,15}', 'cartão de março/2018 (mda.wiki.br, copiado em 2026-11-02)') on conflict (id) do nothing;
insert into requisito_agrupada (id, parent_id, secao, numero, rotulo, texto, faixas, revisao) values ('57e70097-2fc4-5f6e-9897-cf9b188672ed', null, 'VIII - Arte de Acampar', 317, 'VIII.5', 'Com um grupo de, no mínimo, quatro pessoas e com a presença um conselheiro adulto experiente, andar pelo menos 20 quilômetros numa área rural ou deserta, incluindo uma noite ao ar livre ou em barraca. Planejar a expedição em detalhes antes da saída. Durante a caminhada, efetuar anotações sobre o terreno, flora e fauna, observados. Depois, usando as anotações, participar de uma discussão de grupo, dirigida por seu conselheiro.', '{14,15}', 'cartão de março/2018 (mda.wiki.br, copiado em 2026-11-02)') on conflict (id) do nothing;
insert into requisito_agrupada (id, parent_id, secao, numero, rotulo, texto, faixas, revisao) values ('ccba1175-6f62-5fda-a867-f1ef7b63f4e7', null, 'VIII - Arte de Acampar', 318, 'VIII.6', 'Participar com sua unidade de um acampamento com estrutura de pioneiria, planejando o que vai acontecer neste acampamento.', '{15}', 'cartão de março/2018 (mda.wiki.br, copiado em 2026-11-02)') on conflict (id) do nothing;
